import json,sys,re
d=json.load(open(sys.argv[1]))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o[:3]): yield from walk(v,p+f'[{i}]')
    else: yield p,o
keys=[k for k,v in walk(d)]
